const CONFIG = {
  // Edite estes valores antes de ativar o workflow.
  telegramChatId: 'SUBSTITUA_PELO_CHAT_ID',
  cpuLimitPercent: 85,
  memoryLimitPercent: 85,
  diskLimitPercent: 85,
  loadPerCpuLimit: 1.5,
  alertRepeatMinutes: 60,
  rebootWindowMinutes: 10,
};

const input = $input.first().json;
let mode = 'monitor';
try {
  mode = String($('Preparar coleta').first().json.mode || mode);
} catch (_) {}

const decode = (value) => {
  if (!value) return '';
  try { return Buffer.from(String(value), 'base64').toString('utf8'); } catch (_) { return ''; }
};
const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;');
const num = (value, fallback = 0) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};
const parseLines = (stdout) => {
  const result = {};
  for (const line of String(stdout || '').split(/\r?\n/)) {
    const separator = line.indexOf('=');
    if (separator < 1) continue;
    result[line.slice(0, separator)] = line.slice(separator + 1);
  }
  return result;
};
const formatUptime = (seconds) => {
  let remaining = Math.max(0, Math.floor(seconds));
  const days = Math.floor(remaining / 86400); remaining %= 86400;
  const hours = Math.floor(remaining / 3600); remaining %= 3600;
  const minutes = Math.floor(remaining / 60);
  return [days ? `${days}d` : '', hours ? `${hours}h` : '', `${minutes}min`].filter(Boolean).join(' ');
};
const gb = (kb) => `${(num(kb) / 1024 / 1024).toFixed(1)} GB`;

if (input.error || num(input.code, 0) !== 0) {
  const reason = escapeHtml(input.error || input.stderr || `Comando SSH terminou com codigo ${input.code}`);
  return [{ json: {
    chatId: CONFIG.telegramChatId,
    severity: 'critical',
    message: `🚨 <b>MONITOR INDISPONIVEL</b>\n\nNao foi possivel coletar o status do Ubuntu por SSH.\n<b>Motivo:</b> <code>${reason.slice(0, 1200)}</code>\n\nVerifique a credencial SSH, o servico sshd e a rota do container n8n para o host.`,
  } }];
}

const data = parseLines(input.stdout);
mode = data.MODE || mode;
const cpu = num(data.CPU_PERCENT);
const memory = num(data.MEM_PERCENT);
const disk = num(data.DISK_PERCENT);
const cores = Math.max(1, num(data.CPU_CORES, 1));
const load1 = num(data.LOAD_1);
const loadPerCpu = load1 / cores;
const uptimeSeconds = num(data.UPTIME_SECONDS);
const dockerAccess = data.DOCKER_ACCESS === '1';
const n8nRunning = num(data.N8N_RUNNING);
const n8nContainers = decode(data.N8N_CONTAINERS_B64);
const dockerError = decode(data.DOCKER_ERROR_B64);
const alerts = [];

if (cpu >= CONFIG.cpuLimitPercent) alerts.push({ code: 'cpu', text: `CPU em ${cpu.toFixed(1)}% (limite ${CONFIG.cpuLimitPercent}%)` });
if (memory >= CONFIG.memoryLimitPercent) alerts.push({ code: 'memory', text: `Memoria em ${memory.toFixed(1)}% (limite ${CONFIG.memoryLimitPercent}%)` });
if (disk >= CONFIG.diskLimitPercent) alerts.push({ code: 'disk', text: `Disco raiz em ${disk.toFixed(1)}% (limite ${CONFIG.diskLimitPercent}%)` });
if (loadPerCpu >= CONFIG.loadPerCpuLimit) alerts.push({ code: 'load', text: `Carga por CPU em ${loadPerCpu.toFixed(2)} (limite ${CONFIG.loadPerCpuLimit})` });
if (!dockerAccess) alerts.push({ code: 'docker_access', text: `Docker indisponivel para o usuario SSH${dockerError ? `: ${dockerError.slice(0, 180)}` : ''}` });
if (dockerAccess && n8nRunning < 1) alerts.push({ code: 'n8n_stopped', text: 'Nenhum container n8n esta em execucao' });
if (/unhealthy/i.test(n8nContainers)) alerts.push({ code: 'n8n_unhealthy', text: 'O container n8n esta marcado como unhealthy' });
if (uptimeSeconds > 0 && uptimeSeconds < CONFIG.rebootWindowMinutes * 60) alerts.push({ code: 'recent_reboot', text: `Servidor reiniciado ha ${formatUptime(uptimeSeconds)}` });

const hostname = escapeHtml(decode(data.HOSTNAME_B64) || 'servidor');
const os = escapeHtml(decode(data.OS_B64) || 'Linux');
const kernel = escapeHtml(decode(data.KERNEL_B64));
const ip = escapeHtml(decode(data.IP_B64));
const dockerVersion = escapeHtml(decode(data.DOCKER_VERSION_B64) || 'n/d');
const n8nDetails = escapeHtml(n8nContainers || 'nenhum container n8n encontrado').slice(0, 1000);
const alertBlock = alerts.length
  ? `\n\n<b>Problemas encontrados:</b>\n${alerts.map((alert) => `• ${escapeHtml(alert.text)}`).join('\n')}`
  : '';
const report = `<b>Servidor:</b> ${hostname}${ip ? ` (${ip})` : ''}\n<b>Sistema:</b> ${os}${kernel ? ` / ${kernel}` : ''}\n<b>Uptime:</b> ${formatUptime(uptimeSeconds)}\n\n<b>CPU:</b> ${cpu.toFixed(1)}% | ${cores} vCPU | load ${escapeHtml(data.LOAD_1 || '0')}\n<b>Memoria:</b> ${memory.toFixed(1)}% de ${gb(data.MEM_TOTAL_KB)}\n<b>Disco /:</b> ${disk.toFixed(1)}% de ${gb(data.DISK_TOTAL_KB)}\n\n<b>Docker:</b> ${dockerAccess ? 'acessivel' : 'indisponivel'} | v${dockerVersion}\n<b>Containers:</b> ${num(data.DOCKER_RUNNING)} rodando / ${num(data.DOCKER_TOTAL)} total\n<b>n8n:</b> ${n8nRunning} rodando\n<code>${n8nDetails}</code>${alertBlock}`;

const now = Date.now();
let send = mode === 'manual' || mode === 'daily';
let title = alerts.length ? '🚨 ALERTA NO SERVIDOR' : '✅ STATUS DO SERVIDOR';

if (mode === 'monitor') {
  const state = $getWorkflowStaticData('global');
  const fingerprint = alerts.map((alert) => alert.code).sort().join('|');
  const previousStatus = state.lastStatus || 'unknown';
  const lastAlertAt = num(state.lastAlertAt);
  const repeatDue = now - lastAlertAt >= CONFIG.alertRepeatMinutes * 60 * 1000;

  if (alerts.length) {
    send = fingerprint !== state.lastFingerprint || repeatDue;
    if (send) state.lastAlertAt = now;
    state.lastFingerprint = fingerprint;
    state.lastStatus = 'alert';
  } else {
    send = previousStatus === 'alert';
    state.lastFingerprint = '';
    state.lastStatus = 'healthy';
    if (send) title = '✅ SERVIDOR RECUPERADO';
  }
}

if (!send) return [];
return [{ json: {
  chatId: CONFIG.telegramChatId,
  severity: alerts.length ? 'alert' : 'ok',
  message: `${title}\n\n${report}`,
} }];
